&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;&lt;td&gt;&lt;b&gt;Inquisitions&lt;/b&gt;&lt;/td&gt;
        &lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#CONVERSION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Conversion&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#EMPRISONNEMENT&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Emprisonnement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#HERESIE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;H&#233;r&#233;sie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#PERSEVERANCE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Pers&#233;v&#233;rance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#TORTURE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Torture&lt;/a&gt;&lt;/td&gt;
    &lt;/tr&gt;
